<template><main class="page feature-page fragment-page"><header class="topbar"><div><p class="eyebrow">情报站 · 拼图档案</p><h1>情报碎片</h1></div><button @click="router.back()">← 地图</button></header><p class="notice">羽毛：{{ store.feathers }} · 每块碎片 {{ price }} 羽毛</p><section class="feature-grid"><article class="feature-card"><h2>样例：张守田身份线索</h2><p class="muted">无需图片资源：三条结构化线索集齐后自动进入身份鉴别。</p><div v-for="clue in identityCase.clues" :key="clue.id" class="inventory-row"><strong>{{ clue.label }}</strong><span>{{ store.fragments.includes(clue.id) ? clue.content : '未解锁线索' }}</span><button v-if="!store.fragments.includes(clue.id)" :disabled="store.feathers < price" @click="unlockIdentityClue(clue.id)">兑换</button></div><button v-if="identityComplete" class="primary" @click="router.push(`/identity/${identityCase.id}`)">进入身份鉴别</button></article><article v-for="group in groups" :key="group.id" class="feature-card"><h2>{{ group.heroName }}</h2><p class="muted">{{ group.source }}</p><div v-for="fragment in group.fragments" :key="fragment.id" class="inventory-row"><strong>{{ fragment.order }}. {{ fragment.unlocked ? fragment.content : '未解锁碎片' }}</strong><button v-if="!fragment.unlocked" :disabled="store.feathers<price" @click="unlock(fragment.id)">兑换</button></div></article></section></main></template>
<script setup lang="ts">import { computed } from 'vue';import { useRouter } from 'vue-router';import { useGameStore } from '../stores/gameStore';import source from '../../public/data/fragments/tempered_1937.json';import { identityCases } from '../data/resourceData';import { autoSave } from '../engine/SaveManager';const router=useRouter();const store=useGameStore();const price=10;const identityCase=identityCases[0];const identityComplete=computed(()=>identityCase.clues.every(clue=>store.fragments.includes(clue.id)));const groups=computed(()=>source.groups.map(group=>({...group,fragments:group.fragments.map(fragment=>({...fragment,unlocked:store.fragments.includes(fragment.id)||store.fragments.includes(group.id)}))})));async function unlock(id:string){if(store.feathers<price||store.fragments.includes(id))return;store.addFeathers(-price);store.addFragment(id);await autoSave()}async function unlockIdentityClue(id:string){await unlock(id);if(identityCase.clues.every(clue=>store.fragments.includes(clue.id)))router.push(`/identity/${identityCase.id}`)}</script>